function commitEntry(hash, date, message) {
  return new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { line: 280 },
    indent: { left: 360 },
    children: [
      new TextRun({ text: hash + " ", size: 20, color: c(P.accent), font: { ascii: "Consolas", eastAsia: "SimSun" }, bold: true }),
      new TextRun({ text: date + "  ", size: 20, color: c(P.secondary), font: { ascii: "Consolas", eastAsia: "SimSun" } }),
      new TextRun({ text: message, size: 20, color: c(P.body), font: { ascii: "Consolas", eastAsia: "SimSun" } }),
    ],
  });
}

// Table helper
function makeTable(headers, rows) {
  const headerCells = headers.map(h => new TableCell({
    children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: h, bold: true, size: 21, color: "FFFFFF", font: { ascii: "Calibri", eastAsia: "SimHei" } })] })],
    shading: { fill: c(P.primary), type: ShadingType.CLEAR },
    margins: { top: 60, bottom: 60, left: 120, right: 120 },
  }));

  const dataRows = rows.map((row, idx) => new TableRow({
    children: row.map(cell => new TableCell({
      children: [new Paragraph({ alignment: AlignmentType.LEFT, children: [new TextRun({ text: cell, size: 21, color: c(P.body), font: { ascii: "Calibri", eastAsia: "SimSun" } })] })],
      shading: idx % 2 === 0 ? { fill: c(P.surface), type: ShadingType.CLEAR } : undefined,
      margins: { top: 40, bottom: 40, left: 120, right: 120 },
    })),
  }));

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: [new TableRow({ children: headerCells, tableHeader: true }), ...dataRows],
  });
}

